"""字段级影响分析。

直接影响：资产的字段引用与目标字段 ``(schema, version, path)`` 精确相等。
传递影响：从资产引用的具体字段出发，沿跨 Schema ``$ref`` 边正向解析，
若能到达目标字段（精确相等、或祖先/后代包含关系），即构成传递命中。

正向解析从资产引用的 *具体* 路径出发，路径长度随跨边跳数只减不增，因此
即使 Schema 之间存在根级引用环，状态空间也是有限的。传递结果按稳定标识
``(资产, schema, version, 引用路径)`` 去重。
"""

from __future__ import annotations

from dataclasses import dataclass

from . import limits, pointer as ptr
from .errors import ImpactAnalysisTooLarge
from .registry import Registry, RefEdge


@dataclass(frozen=True)
class Reach:
    schema: str
    version: str
    path: str


def _related(a: str, b: str) -> bool:
    return a == b or ptr.is_under(a, b) or ptr.is_under(b, a)


def _build_outgoing(registry: Registry) -> dict[tuple[str, str], list[RefEdge]]:
    outgoing: dict[tuple[str, str], list[RefEdge]] = {}
    for edge in registry.all_edges():
        outgoing.setdefault((edge.src_schema, edge.src_version), []).append(edge)
    for edges in outgoing.values():
        edges.sort(
            key=lambda e: (e.dst_schema, e.dst_version, e.src_path, e.dst_path)
        )
    return outgoing


def forward_reach(
    registry: Registry,
    schema: str,
    version: str,
    path: str,
    outgoing: dict[tuple[str, str], list[RefEdge]] | None = None,
    cache: dict[tuple[str, str, str], list[Reach]] | None = None,
) -> list[Reach]:
    """从一个具体字段出发正向解析跨 Schema 引用，返回可到达的全部字段。

    每条出边满足：边的源路径与当前路径相等，或是当前路径的祖先
    （引用了包含当前字段的子树）；目标侧路径按后缀对齐。
    """
    if cache is not None:
        cached = cache.get((schema, version, path))
        if cached is not None:
            return cached
    if outgoing is None:
        outgoing = _build_outgoing(registry)

    start = Reach(schema, version, path)
    reached: dict[Reach, None] = {start: None}
    queue: list[tuple[Reach, int]] = [(start, 0)]
    edges_walked = 0

    while queue:
        state, depth = queue.pop(0)
        if depth >= limits.MAX_IMPACT_DEPTH:
            raise ImpactAnalysisTooLarge(
                "影响链深度超过公开限制",
                details={
                    "reason": "depth_exceeded",
                    "limit": limits.MAX_IMPACT_DEPTH,
                    "schema": state.schema,
                    "version": state.version,
                    "path": state.path,
                },
            )
        for edge in outgoing.get((state.schema, state.version), ()):
            sp, cp = ptr.parse(edge.src_path), ptr.parse(state.path)
            if not (len(sp) <= len(cp) and cp[: len(sp)] == sp):
                continue
            edges_walked += 1
            if edges_walked > limits.MAX_IMPACT_VISITED:
                raise ImpactAnalysisTooLarge(
                    "影响链引用边数量超过公开限制",
                    details={"reason": "edges_exceeded", "limit": limits.MAX_IMPACT_VISITED},
                )
            suffix = cp[len(sp) :]
            mapped = Reach(
                edge.dst_schema,
                edge.dst_version,
                ptr.format(list(ptr.parse(edge.dst_path)) + list(suffix)),
            )
            if mapped in reached:
                continue
            reached[mapped] = None
            queue.append((mapped, depth + 1))

    del reached[start]
    result = sorted(reached.keys(), key=lambda r: (r.schema, r.version, r.path))
    if cache is not None:
        cache[(schema, version, path)] = result
    return result


def analyze_field(registry: Registry, schema: str, version: str, path: str) -> dict:
    """返回单个字段的影响资产：直接 + 传递（各自稳定排序、去重）。"""
    registry.get_schema(schema, version)

    direct: dict[str, dict] = {}
    transitive_map: dict[tuple[str, str, str, str], dict] = {}
    outgoing = _build_outgoing(registry)
    reach_cache: dict[tuple[str, str, str], list[Reach]] = {}

    for asset in registry.all_assets():
        for ref in asset.refs:
            if ref.schema == schema and ref.version == version:
                if ref.path == path:
                    direct.setdefault(
                        asset.id,
                        {"asset_id": asset.id, "name": asset.name, "kind": asset.kind},
                    )
                    continue

            # 传递：从资产引用的具体字段正向解析到目标字段。
            reachable = forward_reach(
                registry, ref.schema, ref.version, ref.path, outgoing, reach_cache
            )
            matched = [r for r in reachable if r.schema == schema and r.version == version
                       and _related(r.path, path)]
            if not matched:
                continue
            key = (asset.id, ref.schema, ref.version, ref.path)
            entry = transitive_map.get(key)
            if entry is None:
                entry = {
                    "asset_id": asset.id,
                    "name": asset.name,
                    "kind": asset.kind,
                    "schema": ref.schema,
                    "version": ref.version,
                    "path": ref.path,
                    "matched_paths": [],
                }
                transitive_map[key] = entry
            for r in matched:
                if r.path not in entry["matched_paths"]:
                    entry["matched_paths"].append(r.path)

    transitive = list(transitive_map.values())
    for entry in transitive:
        entry["matched_paths"].sort(key=lambda p: (ptr.parse(p), p))

    if len(direct) + len(transitive) > limits.MAX_IMPACT_ASSETS:
        raise ImpactAnalysisTooLarge(
            "影响资产数量超过公开限制",
            details={"reason": "assets_exceeded", "limit": limits.MAX_IMPACT_ASSETS},
        )

    return {
        "schema": schema,
        "version": version,
        "path": path,
        "direct_assets": [direct[k] for k in sorted(direct)],
        "transitive_assets": sorted(
            transitive,
            key=lambda a: (a["asset_id"], a["schema"], a["version"], a["path"]),
        ),
    }

"""字段影响链路解释。

在字段级影响分析（:mod:`meta_catalog.impact`）的命中口径之上，解释每个资产
*为什么* 受所查字段影响：

  * 直接命中：资产引用的字段与所查字段精确相等，给出零步链，
    ``source == target == 所查字段``；
  * 传递命中：从资产引用的具体字段出发，沿跨 Schema ``$ref`` 边正向解析，
    到达所查版本中与所查字段相等或祖先/后代包含的命中路径，给出实际步进链。

同一 ``(source, target)`` 只保留一条最短链；等长时按步进定位元组
（逐步 ``from``/``to`` 的 ``(schema, version, path)``）取稳定最小者。
同一资产的直接与传递来源分别保留，``impact_kind`` 按实际命中合并为
``direct`` / ``transitive`` / ``both``。

正向解析路径长度随跨边跳数只减不增，引用环不会产生重复链或无界结果。
本模块只读注册簿：不注册资源、不生成报告、不写入检索索引。
"""

from __future__ import annotations

from typing import Any

from . import limits, pointer as ptr
from .errors import ImpactAnalysisTooLarge, NotFoundError
from .impact import _build_outgoing, _related
from .registry import Registry

# 状态定位：(schema, version, path) 三元组。
_State = tuple[str, str, str]


def _locator(state: _State) -> dict[str, Any]:
    return {"schema": state[0], "version": state[1], "path": state[2]}


def _resolve_asset_ids(
    registry: Registry, asset_ids: list[str] | None
) -> list[str]:
    """校验并去重资产选择，返回按 asset_id 升序的入选清单。

    ``None`` 覆盖全部资产；空列表不选任何资产；未知资产抛
    :class:`NotFoundError`。
    """
    if asset_ids is None:
        return [a.id for a in registry.all_assets()]
    known = {a.id for a in registry.all_assets()}
    unique: set[str] = set()
    for aid in asset_ids:
        if not isinstance(aid, str) or not aid or aid not in known:
            raise NotFoundError(f"资产 {aid!r} 不存在", details={"asset_id": aid})
        unique.add(aid)
    return sorted(unique)


def _match_chains(
    outgoing: dict[tuple[str, str], list],
    start: _State,
    query: _State,
) -> list[dict[str, Any]]:
    """从 ``start`` 正向 BFS，返回到达全部命中状态的最短链（按目标排序）。

    命中状态：位于所查 ``(schema, version)`` 且路径与所查路径相等或
    祖先/后代包含。每个状态的父指针在首次发现时确定；邻接状态按定位
    元组升序扩展，因此等长链中保留的是步进定位元组稳定最小者。
    """
    parent: dict[_State, _State | None] = {start: None}
    queue: list[tuple[_State, int]] = [(start, 0)]
    matched: list[_State] = []
    edges_walked = 0
    head = 0
    while head < len(queue):
        state, depth = queue[head]
        head += 1
        if depth >= limits.MAX_IMPACT_DEPTH:
            raise ImpactAnalysisTooLarge(
                "影响链深度超过公开限制",
                details={
                    "reason": "depth_exceeded",
                    "limit": limits.MAX_IMPACT_DEPTH,
                    "schema": state[0],
                    "version": state[1],
                    "path": state[2],
                },
            )
        sp_path = ptr.parse(state[2])
        mapped_states: set[_State] = set()
        for edge in outgoing.get((state[0], state[1]), ()):
            ep = ptr.parse(edge.src_path)
            if not (len(ep) <= len(sp_path) and sp_path[: len(ep)] == ep):
                continue
            edges_walked += 1
            if edges_walked > limits.MAX_IMPACT_VISITED:
                raise ImpactAnalysisTooLarge(
                    "影响链引用边数量超过公开限制",
                    details={
                        "reason": "edges_exceeded",
                        "limit": limits.MAX_IMPACT_VISITED,
                    },
                )
            suffix = sp_path[len(ep) :]
            mapped_states.add(
                (
                    edge.dst_schema,
                    edge.dst_version,
                    ptr.format(list(ptr.parse(edge.dst_path)) + list(suffix)),
                )
            )
        for nxt in sorted(mapped_states):
            if nxt in parent:
                continue
            parent[nxt] = state
            queue.append((nxt, depth + 1))
            if (
                nxt[0] == query[0]
                and nxt[1] == query[1]
                and _related(nxt[2], query[2])
            ):
                matched.append(nxt)

    chains: list[dict[str, Any]] = []
    for target in sorted(matched):
        states: list[_State] = []
        cur: _State | None = target
        while cur is not None:
            states.append(cur)
            cur = parent[cur]
        states.reverse()
        chains.append(
            {
                "source": _locator(states[0]),
                "steps": [
                    {"from": _locator(states[i]), "to": _locator(states[i + 1])}
                    for i in range(len(states) - 1)
                ],
                "target": _locator(states[-1]),
            }
        )
    return chains


def explain_field(
    registry: Registry,
    schema: str,
    version: str,
    path: str,
    asset_ids: list[str] | None,
) -> dict[str, Any]:
    """按资产解释所查字段的影响链路（只读，不改动任何注册内容）。"""
    registry.get_schema(schema, version)  # 未知 Schema/版本抛 NotFoundError
    if not isinstance(path, str) or (path and not path.startswith("/")):
        raise NotFoundError(
            f"字段 {schema}@{version}{path!r} 不可达",
            details={"schema": schema, "version": version, "path": path},
        )
    if not registry.logical_path_exists(schema, version, path):
        raise NotFoundError(
            f"字段 {schema}@{version}{path} 不可达",
            details={"schema": schema, "version": version, "path": path},
        )
    selected = _resolve_asset_ids(registry, asset_ids)

    query: _State = (schema, version, path)
    outgoing = _build_outgoing(registry)
    assets = {a.id: a for a in registry.all_assets()}

    entries: list[dict[str, Any]] = []
    for aid in selected:
        asset = assets[aid]
        chains: list[dict[str, Any]] = []
        seen: set[tuple[_State, _State]] = set()
        has_direct = False
        has_transitive = False
        for ref in asset.refs:
            if (ref.schema, ref.version, ref.path) == query:
                # 直接命中：零步链，source 与 target 都是所查字段。
                has_direct = True
                key = (query, query)
                if key not in seen:
                    seen.add(key)
                    chains.append(
                        {
                            "source": _locator(query),
                            "steps": [],
                            "target": _locator(query),
                        }
                    )
                continue
            for chain in _match_chains(
                outgoing, (ref.schema, ref.version, ref.path), query
            ):
                has_transitive = True
                s, t = chain["source"], chain["target"]
                key = (
                    (s["schema"], s["version"], s["path"]),
                    (t["schema"], t["version"], t["path"]),
                )
                if key in seen:
                    continue
                seen.add(key)
                chains.append(chain)
        if not chains:
            continue
        if len(entries) + 1 > limits.MAX_IMPACT_ASSETS:
            raise ImpactAnalysisTooLarge(
                "影响资产数量超过公开限制",
                details={
                    "reason": "assets_exceeded",
                    "limit": limits.MAX_IMPACT_ASSETS,
                },
            )
        chains.sort(
            key=lambda c: (
                c["source"]["schema"],
                c["source"]["version"],
                c["source"]["path"],
                c["target"]["schema"],
                c["target"]["version"],
                c["target"]["path"],
            )
        )
        impact_kind = (
            "both" if has_direct and has_transitive
            else "direct" if has_direct
            else "transitive"
        )
        entries.append(
            {
                "asset_id": asset.id,
                "name": asset.name,
                "kind": asset.kind,
                "impact_kind": impact_kind,
                "chains": chains,
            }
        )

    return {
        "schema": schema,
        "version": version,
        "path": path,
        "assets": entries,
    }

"""注册簿：Schema 版本、目录资产与跨 Schema 引用关系。

注册内容不可变：任何读取都返回深拷贝，比较、影响分析和检索都无法改动
既有注册结果、版本关系与资产依赖关系。

跨 Schema 引用约定：``$ref`` 写作 ``"<SchemaName>@<version>#<JSONPointer>"``，
例如 ``"Address@1.0#/properties/street"``；``#`` 后为空表示引用文档根。
文档内引用沿用标准 ``"#/..."`` 形式。
"""

from __future__ import annotations

import copy
import re
from dataclasses import dataclass
from typing import Any

from .errors import AlreadyExistsError, NotFoundError
from . import pointer as ptr
from .schema_fields import expand as _expand_fields

_REF_RE = re.compile(r"^(?P<name>[^@#/\s]+)@(?P<version>[^@#\s]+)#(?P<pointer>.*)$")
_NAME_RE = re.compile(r"^[A-Za-z0-9_.\-]+$")


def validate_name(name: str, *, what: str = "名称") -> None:
    if not isinstance(name, str) or not name or not _NAME_RE.match(name):
        raise ValueError(f"非法{what}: {name!r}（只允许字母、数字、_、.、-）")


@dataclass(frozen=True)
class SchemaVersion:
    name: str
    version: str
    document: Any
    title: str | None


@dataclass(frozen=True)
class FieldRef:
    """资产对某 Schema 某版本某字段路径的直接引用。"""

    schema: str
    version: str
    path: str  # JSON Pointer，"" 表示根


@dataclass(frozen=True)
class Asset:
    id: str
    name: str
    kind: str
    refs: tuple[FieldRef, ...]


@dataclass(frozen=True)
class RefEdge:
    """一条跨 Schema ``$ref`` 边：src 字段定义引用了 dst 字段节点。"""

    src_schema: str
    src_version: str
    src_path: str
    dst_schema: str
    dst_version: str
    dst_path: str


def parse_external_ref(ref: str) -> tuple[str, str, str] | None:
    """解析跨 Schema 引用；非此外部形式返回 ``None``。"""
    m = _REF_RE.match(ref)
    if not m:
        return None
    return m.group("name"), m.group("version"), m.group("pointer")


def extract_ref_edges(name: str, version: str, document: Any) -> list[RefEdge]:
    """提取文档内全部跨 Schema 引用边（原始文档指针，按出现顺序排序）。

    指针在注册时再结合两端文档解析为逻辑字段路径。
    """
    edges: list[RefEdge] = []

    def walk(node: Any, path: str, seen: frozenset[int]) -> None:
        if isinstance(node, bool) or not isinstance(node, (dict, list)):
            return
        if id(node) in seen:
            return
        seen = seen | {id(node)}
        if isinstance(node, dict):
            ref = node.get("$ref")
            if isinstance(ref, str):
                parsed = parse_external_ref(ref)
                if parsed is not None:
                    dst_name, dst_version, fragment = parsed
                    if fragment and not fragment.startswith("/"):
                        fragment = "/" + fragment
                    edges.append(
                        RefEdge(name, version, path, dst_name, dst_version, fragment)
                    )
            for k in sorted(node.keys()):
                walk(node[k], path + "/" + _escape(k) if path else "/" + _escape(k), seen)
        else:
            for i, v in enumerate(node):
                walk(v, f"{path}/{i}" if path else f"/{i}", seen)

    walk(document, "", frozenset())
    edges.sort(key=lambda e: (e.src_path, e.dst_schema, e.dst_version, e.dst_path))
    return edges


def _escape(token: str) -> str:
    return token.replace("~", "~0").replace("/", "~1")


class Registry:
    def __init__(self) -> None:
        self._schemas: dict[tuple[str, str], SchemaVersion] = {}
        # name -> 按注册顺序保存的版本列表
        self._versions: dict[str, list[str]] = {}
        self._assets: dict[str, Asset] = {}
        self._edges: dict[tuple[str, str], tuple[RefEdge, ...]] = {}

    # ------------------------------------------------------------------ schema
    def register_schema(self, name: str, version: str, document: Any) -> SchemaVersion:
        validate_name(name, what="Schema 名称")
        validate_name(version, what="版本号")
        key = (name, version)
        if key in self._schemas:
            raise AlreadyExistsError(
                f"Schema {name}@{version} 已注册，注册内容不可覆盖",
                details={"schema": name, "version": version},
            )
        # 跨 Schema 引用允许前向（目标稍后注册），因此引用环也可注册；
        # 目标缺失或目标字段不存在时，影响传播自然不会产生命中。
        raw_edges = extract_ref_edges(name, version, document)
        edges: list[RefEdge] = []
        for e in raw_edges:
            dst_record = self._schemas.get((e.dst_schema, e.dst_version))
            dst_raw = e.dst_path if e.dst_path else ""
            if dst_record is not None:
                dst_logical = ptr.resolve_logical(dst_record.document, dst_raw)
                if dst_logical is None or dst_logical not in _expand_fields(dst_record.document):
                    # 目标已注册但字段不存在：属于确定的非法引用。
                    raise NotFoundError(
                        f"跨 Schema 引用 {e.dst_schema}@{e.dst_version}{dst_raw} 的目标字段不存在",
                        details={
                            "schema": e.dst_schema,
                            "version": e.dst_version,
                            "path": dst_raw,
                        },
                    )
                final_dst = dst_logical
            else:
                final_dst = ptr.normalize_field_pointer(dst_raw)
            src_logical = ptr.resolve_logical(document, e.src_path)
            edges.append(
                RefEdge(
                    name,
                    version,
                    src_logical or ptr.normalize_field_pointer(e.src_path),
                    e.dst_schema,
                    e.dst_version,
                    final_dst,
                )
            )
        edges.sort(key=lambda x: (x.src_path, x.dst_schema, x.dst_version, x.dst_path))
        title = None
        if isinstance(document, dict):
            t = document.get("title")
            title = t if isinstance(t, str) else None
        record = SchemaVersion(name, version, copy.deepcopy(document), title)
        self._schemas[key] = record
        self._versions.setdefault(name, []).append(version)
        self._edges[key] = tuple(edges)
        return record

    def get_schema(self, name: str, version: str) -> SchemaVersion:
        key = (name, version)
        if key not in self._schemas:
            raise NotFoundError(
                f"Schema {name}@{version} 不存在",
                details={"schema": name, "version": version},
            )
        return self._schemas[key]

    def has_schema(self, name: str, version: str) -> bool:
        return (name, version) in self._schemas

    def schema_document(self, name: str, version: str) -> Any:
        return copy.deepcopy(self.get_schema(name, version).document)

    def list_versions(self, name: str) -> list[str]:
        if name not in self._versions:
            raise NotFoundError(f"Schema {name} 不存在", details={"schema": name})
        return list(self._versions[name])

    def edges(self, name: str, version: str) -> tuple[RefEdge, ...]:
        return self._edges.get((name, version), ())

    def all_edges(self) -> list[RefEdge]:
        out: list[RefEdge] = []
        for key in sorted(self._edges):
            out.extend(self._edges[key])
        return out

    def all_schemas(self) -> list[SchemaVersion]:
        return [self._schemas[k] for k in sorted(self._schemas)]

    def registered_pairs(self) -> list[tuple[str, str]]:
        """按全局注册顺序返回全部 ``(名称, 版本)``。"""
        return list(self._schemas.keys())

    def logical_path_exists(self, schema: str, version: str, path: str) -> bool:
        """判断逻辑字段路径是否可达（含沿跨 Schema ``$ref`` 跳转解析）。"""
        return self._logical_path_exists(
            schema, version, path, frozenset({(schema, version)})
        )

    def _logical_path_exists(
        self, schema: str, version: str, path: str, stack: frozenset[tuple[str, str]]
    ) -> bool:
        """判断逻辑字段路径是否可达，沿跨 Schema ``$ref`` 边跳转解析。"""
        if (schema, version) not in self._schemas:
            return False
        document = self._schemas[(schema, version)].document
        valid_paths = _expand_fields(document)
        if path in valid_paths:
            return True

        target_segs = ptr.parse(path)
        # 选择最长的、能覆盖目标路径前缀的出边。
        best = None
        for edge in self._edges.get((schema, version), ()):  # type: RefEdge
            esegs = ptr.parse(edge.src_path)
            if len(esegs) <= len(target_segs) and target_segs[: len(esegs)] == esegs:
                if best is None or len(esegs) > len(ptr.parse(best.src_path)):
                    best = edge
        if best is None:
            return False
        dst_key = (best.dst_schema, best.dst_version)
        if dst_key in stack:
            return False
        suffix = target_segs[len(ptr.parse(best.src_path)) :]
        resolved = ptr.format(list(ptr.parse(best.dst_path)) + list(suffix))
        return self._logical_path_exists(
            best.dst_schema, best.dst_version, resolved, stack | {dst_key}
        )

    # ------------------------------------------------------------------- asset
    def register_asset(
        self,
        asset_id: str,
        name: str,
        kind: str,
        refs: list[FieldRef] | list[dict] | None = None,
    ) -> Asset:
        validate_name(asset_id, what="资产标识")
        if not isinstance(name, str) or not name:
            raise ValueError("资产名称必须是非空字符串")
        if not isinstance(kind, str) or not kind:
            raise ValueError("资产类型必须是非空字符串")
        if asset_id in self._assets:
            raise AlreadyExistsError(
                f"资产 {asset_id} 已注册", details={"asset": asset_id}
            )

        normalized: list[FieldRef] = []
        seen: set[tuple[str, str, str]] = set()
        for raw in refs or []:
            if isinstance(raw, FieldRef):
                r = raw
            else:
                r = FieldRef(raw["schema"], str(raw["version"]), raw.get("path", ""))
            validate_name(r.schema, what="引用 Schema 名称")
            record = self.get_schema(r.schema, r.version)
            if r.path and not r.path.startswith("/"):
                raise ValueError(f"资产引用字段路径必须是 JSON Pointer: {r.path!r}")
            candidate_paths = []
            contextual = ptr.resolve_logical(record.document, r.path)
            if contextual is not None:
                candidate_paths.append(contextual)
            text_normalized = ptr.normalize_field_pointer(r.path)
            for cand in (text_normalized, r.path):
                if cand not in candidate_paths:
                    candidate_paths.append(cand)

            resolved_path = next(
                (
                    cand
                    for cand in candidate_paths
                    if self._logical_path_exists(
                        r.schema, r.version, cand, frozenset({(r.schema, r.version)})
                    )
                ),
                None,
            )
            if resolved_path is None:
                raise NotFoundError(
                    f"资产引用的字段 {r.schema}@{r.version}{text_normalized} 不存在",
                    details={
                        "schema": r.schema,
                        "version": r.version,
                        "path": text_normalized,
                    },
                )
            r = FieldRef(r.schema, r.version, resolved_path)
            dedup_key = (r.schema, r.version, r.path)
            if dedup_key in seen:
                continue
            seen.add(dedup_key)
            normalized.append(r)

        normalized.sort(key=lambda r: (r.schema, r.version, r.path))
        asset = Asset(asset_id, name, kind, tuple(normalized))
        self._assets[asset_id] = asset
        return asset

    def get_asset(self, asset_id: str) -> Asset:
        if asset_id not in self._assets:
            raise NotFoundError(f"资产 {asset_id} 不存在", details={"asset": asset_id})
        return self._assets[asset_id]

    def all_assets(self) -> list[Asset]:
        return [self._assets[k] for k in sorted(self._assets)]

"""字段路径工具。

字段路径采用 JSON Pointer（RFC 6901）表示，例如 ``/properties/name``、
``/properties/a~1b``。根对象本身用空串 ``""`` 表示。
"""

from __future__ import annotations

from typing import Any


def escape(token: str) -> str:
    """转义单个路径段。"""
    return token.replace("~", "~0").replace("/", "~1")


def unescape(token: str) -> str:
    """反转义单个路径段。"""
    return token.replace("~1", "/").replace("~0", "~")


def parse(path: str) -> tuple[str, ...]:
    """把 JSON Pointer 解析为路径段元组；根路径返回空元组。"""
    if path == "":
        return ()
    if not path.startswith("/"):
        raise ValueError(f"非法 JSON Pointer: {path!r}")
    return tuple(unescape(seg) for seg in path[1:].split("/"))


def format(segments: tuple[str, ...] | list[str]) -> str:
    """把路径段组装为 JSON Pointer。"""
    return "".join("/" + escape(str(seg)) for seg in segments)


def child(path: str, segment: str) -> str:
    """返回某路径下的子路径。"""
    return (path + "/" + escape(segment)) if path else "/" + escape(segment)


def parent(path: str) -> str | None:
    """返回父路径；根路径返回 ``None``。"""
    segs = parse(path)
    if not segs:
        return None
    return format(segs[:-1])


def is_under(prefix: str, path: str) -> bool:
    """``path`` 是否位于 ``prefix`` 子树内（含自身）。"""
    p, c = parse(prefix), parse(path)
    return len(c) >= len(p) and c[: len(p)] == p


def resolve(doc: Any, path: str) -> Any:
    """在文档中按 JSON Pointer 取值，缺段/越界/类型不符时抛 KeyError。"""
    cur: Any = doc
    for seg in parse(path):
        if isinstance(cur, dict):
            if seg not in cur:
                raise KeyError(path)
            cur = cur[seg]
        elif isinstance(cur, list):
            try:
                idx = int(seg)
            except ValueError as exc:
                raise KeyError(path) from exc
            if not 0 <= idx < len(cur):
                raise KeyError(path)
            cur = cur[idx]
        else:
            raise KeyError(path)
    return cur


def normalize_field_pointer(path: str) -> str:
    """把 Schema 文档指针 *无上下文地* 规整为逻辑字段路径。

    注意：纯文本规整无法区分「名为 ``items`` 的属性」与 ``items`` 关键字，
    资产/引用路径应优先使用逻辑路径，或用 :func:`resolve_logical` 结合
    文档解析。
    """
    segs = list(parse(path))
    out: list[str] = []
    for i, seg in enumerate(segs):
        if seg in ("properties", "prefixItems"):
            continue
        if seg == "additionalProperties":
            out.append("*")
        elif seg == "items":
            # 元组形式 items/0 展开为数组下标；单 Schema items 展开为 -。
            if i + 1 < len(segs) and segs[i + 1].isdigit():
                continue
            out.append("-")
        else:
            out.append(seg)
    return format(out)


def resolve_logical(document: Any, raw_path: str) -> str | None:
    """结合文档结构，把文档指针解析为逻辑字段路径；不可解析返回 ``None``。

    遍历规则与字段展开一致：``properties`` 段省略（其后必为属性名，即使
    名字恰好叫 ``items``）；单 Schema ``items`` 段映射为 ``-``；
    ``additionalProperties`` 映射为 ``*``；``$defs``/``definitions`` 保留。
    """
    segs = parse(raw_path)
    node: Any = document
    logical: list[str] = []
    i = 0
    while i < len(segs):
        seg = segs[i]
        if isinstance(node, dict):
            props = node.get("properties")
            if seg == "properties" and isinstance(props, dict):
                # 容器关键字与其后的属性名在同一步消费，避免属性名与
                # Schema 关键字（如名为 items 的属性）混淆。
                if i + 1 >= len(segs):
                    return None
                name = segs[i + 1]
                if name not in props:
                    return None
                node = props[name]
                logical.append(name)
                i += 2
                continue
            pats = node.get("patternProperties")
            if seg == "patternProperties" and isinstance(pats, dict):
                if i + 1 >= len(segs):
                    return None
                name = segs[i + 1]
                if name not in pats:
                    return None
                node = pats[name]
                logical.append(escape(name))
                i += 2
                continue
            ap = node.get("additionalProperties")
            if seg == "additionalProperties" and isinstance(ap, (dict, bool)):
                node = ap
                logical.append("*")
                i += 1
                continue
            items = node.get("items")
            if seg == "items" and isinstance(items, (dict, bool)):
                node = items
                logical.append("-")
                i += 1
                continue
            pre = node.get("prefixItems")
            if seg == "prefixItems" and isinstance(pre, list):
                if i + 1 >= len(segs):
                    return None
                try:
                    idx = int(segs[i + 1])
                except ValueError:
                    return None
                if not 0 <= idx < len(pre):
                    return None
                node = pre[idx]
                logical.append(str(idx))
                i += 2
                continue
            if seg in ("$defs", "definitions") and isinstance(node.get(seg), dict):
                if i + 1 >= len(segs):
                    return None
                name = segs[i + 1]
                if name not in node[seg]:
                    return None
                node = node[seg][name]
                logical.extend((seg, name))
                i += 2
                continue
            if seg not in node:
                return None
            node = node[seg]
            logical.append(seg)
            i += 1
        elif isinstance(node, list):
            try:
                idx = int(seg)
            except ValueError:
                return None
            if not 0 <= idx < len(node):
                return None
            node = node[idx]
            logical.append(seg)
            i += 1
        else:
            return None
    return format(logical)

"""变更预检（``preview_changes``）。

对一批尚未提交的 Schema 变更做只读预检：不注册 Schema、不生成变更报告、
不写入检索索引，既有注册内容、报告库与检索行为完全不受影响。

批次元素形如::

    {"schema": "Person", "version": "1.0", "changeType": "add_field",
     "path": "/email", "definition": {"type": "string"}}

``changeType`` 仅限 ``add_field`` / ``remove_field`` / ``change_type`` /
``compatibility_check`` / ``unregister_schema``：

  * ``add_field`` / ``change_type`` 携带逻辑字段路径 ``path`` 与字段定义
    ``definition``；
  * ``remove_field`` 携带逻辑字段路径 ``path``；
  * ``compatibility_check`` 携带候选 Schema 文档 ``candidate``；
  * ``unregister_schema`` 仅由 ``schema`` + ``version`` 定位版本。

校验与错误口径：

  * 缺字段、未知 ``changeType``、非法逻辑 JSONPointer、同一路径重复出现但
    内容不匹配、字段定义/候选文档不是合法 JSON Schema，抛
    :class:`SchemaComparisonInvalid`；
  * 引用的 Schema 或版本未注册，抛 :class:`NotFoundError`；
  * 影响链深度、引用边数或影响资产数超过公开限制，抛
    :class:`ImpactAnalysisTooLarge`；
  * 批次内部矛盾（同一路径被不同变更类型覆盖、``add_field`` 落在已注册
    字段上、``unregister_schema`` 与同版本其他变更并存）或
    ``remove_field`` / ``change_type`` 指向未注册字段时，不抛错，返回
    ``accepted=False`` 与 ``conflicts``（``CHANGE_CONFLICT`` /
    ``FIELD_NOT_FOUND``），此时 ``impactedItems`` 与 ``searchPreview``
    为空集合。

兼容性判定沿用既有字段级比较（:func:`meta_catalog.schema_fields.classify_pair`
与 :func:`meta_catalog.compare.build_report`）；``compatibility_check`` 中
旧版本未定义的扩展字段不新增要求，一律按 ``compatible`` 计入预览。
"""

from __future__ import annotations

import copy
import json
from typing import Any

from . import compare as compare_mod
from . import limits
from . import pointer as ptr
from . import schema_fields as sf
from .errors import ImpactAnalysisTooLarge, SchemaComparisonInvalid
from .impact import _build_outgoing, analyze_field, forward_reach
from .indexing import change_doc
from .registry import Registry
from .search import SearchIndex
from .validator import validate_schema

ADD_FIELD = "add_field"
REMOVE_FIELD = "remove_field"
CHANGE_TYPE = "change_type"
COMPATIBILITY_CHECK = "compatibility_check"
UNREGISTER_SCHEMA = "unregister_schema"

CHANGE_TYPES = (
    ADD_FIELD,
    REMOVE_FIELD,
    CHANGE_TYPE,
    COMPATIBILITY_CHECK,
    UNREGISTER_SCHEMA,
)

CHANGE_CONFLICT = "CHANGE_CONFLICT"
FIELD_NOT_FOUND = "FIELD_NOT_FOUND"

# search 参数沿用 MetaCatalog.search 的检索条件。
_SEARCH_KEYS = frozenset(
    {
        "keyword",
        "schema",
        "version",
        "field_path",
        "change_kind",
        "compatibility",
        "asset_name",
        "doc_type",
        "limit",
    }
)

_PATH_TYPES = (ADD_FIELD, REMOVE_FIELD, CHANGE_TYPE)


def preview_changes(
    registry: Registry,
    index: SearchIndex,
    changes: Any,
    search: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """预检一批变更，返回 ``accepted`` / ``conflicts`` / ``impactedItems`` /
    ``searchPreview``。只读：不触碰注册簿、报告库与检索索引。"""
    search_kwargs = _validate_search(search)
    normalized = _validate_batch(changes)

    empty_impacts: dict[str, list] = {"direct": [], "transitive": []}
    empty_preview: dict[str, list] = {"added": [], "removed": [], "replaced": []}
    if not normalized:
        return {
            "accepted": True,
            "conflicts": [],
            "impactedItems": empty_impacts,
            "searchPreview": empty_preview,
        }

    # 存在性：Schema/版本未注册抛 NotFoundError（在冲突判定之前）。
    for ch in normalized:
        registry.get_schema(ch["schema"], ch["version"])

    conflicts = _find_conflicts(registry, normalized)
    if conflicts:
        return {
            "accepted": False,
            "conflicts": conflicts,
            "impactedItems": empty_impacts,
            "searchPreview": empty_preview,
        }

    # compatibility_check 的比较报告只算一次，影响汇总与检索预览共用。
    reports = {
        ch["index"]: _compat_report(registry, ch)
        for ch in normalized
        if ch["changeType"] == COMPATIBILITY_CHECK
    }
    impacted = _collect_impacts(registry, normalized, reports)
    preview = _build_search_preview(registry, index, normalized, reports, search_kwargs)
    return {
        "accepted": True,
        "conflicts": [],
        "impactedItems": impacted,
        "searchPreview": preview,
    }


# ---------------------------------------------------------------- 输入校验
def _validate_search(search: Any) -> dict[str, Any] | None:
    """校验 search 条件；返回可传给 ``SearchIndex.search`` 的 kwargs。"""
    if search is None:
        return None
    if not isinstance(search, dict):
        raise SchemaComparisonInvalid(
            "search 必须是检索条件字典",
            details={"reason": "search_not_mapping"},
        )
    unknown = sorted(k for k in search if k not in _SEARCH_KEYS)
    if unknown:
        raise SchemaComparisonInvalid(
            f"search 含未知检索条件: {unknown}",
            details={"reason": "search_unknown_filter", "filters": unknown},
        )
    return dict(search)


def _validate_batch(changes: Any) -> list[dict[str, Any]]:
    """结构校验与规范化；失败抛 :class:`SchemaComparisonInvalid`。

    返回按原始顺序的规范化变更列表（完全相同的重复条目已去重，
    ``index`` 为首次出现的位置）。
    """
    if not isinstance(changes, list):
        raise SchemaComparisonInvalid(
            "changes 必须是 JSON 列表",
            details={"reason": "changes_not_list"},
        )

    normalized: list[dict[str, Any]] = []
    seen: set[tuple] = set()
    content_by_target: dict[tuple, str] = {}
    for i, raw in enumerate(changes):
        if not isinstance(raw, dict):
            raise SchemaComparisonInvalid(
                f"第 {i} 条变更必须是对象",
                details={"reason": "change_not_object", "index": i},
            )
        ch = _normalize_change(raw, i)
        content = _canonical_content(ch)

        if ch["changeType"] in _PATH_TYPES:
            target = (ch["schema"], ch["version"], ch["changeType"], ch["path"])
            # 重复路径内容不匹配：请求本身非法。
            if target in content_by_target and content_by_target[target] != content:
                raise SchemaComparisonInvalid(
                    f"第 {i} 条变更与之前同路径条目的内容不匹配",
                    details={
                        "reason": "duplicate_content_mismatch",
                        "index": i,
                        "schema": ch["schema"],
                        "version": ch["version"],
                        "changeType": ch["changeType"],
                        "path": ch["path"],
                    },
                )
            content_by_target.setdefault(target, content)
            dedup_key = (target, content)
        else:
            # compatibility_check / unregister_schema：完全相同才去重，
            # 不同候选文档的兼容性检查相互独立。
            dedup_key = (
                ch["schema"],
                ch["version"],
                ch["changeType"],
                content,
            )
        if dedup_key in seen:
            continue
        seen.add(dedup_key)
        normalized.append(ch)
    return normalized


def _normalize_change(raw: dict, index: int) -> dict[str, Any]:
    def missing(name: str) -> SchemaComparisonInvalid:
        return SchemaComparisonInvalid(
            f"第 {index} 条变更缺少字段 {name!r}",
            details={"reason": "missing_field", "index": index, "field": name},
        )

    for key in ("schema", "version", "changeType"):
        if key not in raw:
            raise missing(key)
    schema, version, ctype = raw["schema"], raw["version"], raw["changeType"]
    if not isinstance(schema, str) or not schema:
        raise SchemaComparisonInvalid(
            f"第 {index} 条变更的 schema 必须是非空字符串",
            details={"reason": "invalid_schema", "index": index},
        )
    if not isinstance(version, str) or not version:
        raise SchemaComparisonInvalid(
            f"第 {index} 条变更的 version 必须是非空字符串",
            details={"reason": "invalid_version", "index": index},
        )
    if ctype not in CHANGE_TYPES:
        raise SchemaComparisonInvalid(
            f"第 {index} 条变更的 changeType 未知: {ctype!r}",
            details={
                "reason": "unknown_change_type",
                "index": index,
                "changeType": ctype,
            },
        )

    ch: dict[str, Any] = {
        "index": index,
        "schema": schema,
        "version": version,
        "changeType": ctype,
    }
    if ctype in _PATH_TYPES:
        ch["path"] = _require_path(raw, index)
    if ctype in (ADD_FIELD, CHANGE_TYPE):
        if "definition" not in raw:
            raise missing("definition")
        validate_schema(raw["definition"])
        ch["definition"] = copy.deepcopy(raw["definition"])
    if ctype == COMPATIBILITY_CHECK:
        if "candidate" not in raw:
            raise missing("candidate")
        validate_schema(raw["candidate"])
        ch["candidate"] = copy.deepcopy(raw["candidate"])
    return ch


def _require_path(raw: dict, index: int) -> str:
    if "path" not in raw:
        raise SchemaComparisonInvalid(
            f"第 {index} 条变更缺少字段 'path'",
            details={"reason": "missing_field", "index": index, "field": "path"},
        )
    path = raw["path"]
    try:
        if not isinstance(path, str):
            raise ValueError
        ptr.parse(path)
    except ValueError as exc:
        raise SchemaComparisonInvalid(
            f"第 {index} 条变更的 path 不是合法逻辑 JSONPointer: {path!r}",
            details={"reason": "invalid_pointer", "index": index, "path": path},
        ) from exc
    return path


def _canonical_content(ch: dict[str, Any]) -> str:
    """用于重复检测的内容指纹（不含定位字段）。"""
    parts: list[Any] = []
    if "definition" in ch:
        parts.append(ch["definition"])
    if "candidate" in ch:
        parts.append(ch["candidate"])
    return json.dumps(parts, sort_keys=True, ensure_ascii=False, separators=(",", ":"))


# ---------------------------------------------------------------- 冲突检测
def _find_conflicts(
    registry: Registry, changes: list[dict[str, Any]]
) -> list[dict[str, Any]]:
    """收集批次矛盾与未注册字段引用（不抛错，全部列出）。"""
    conflicts: list[dict[str, Any]] = []
    fields_cache: dict[tuple[str, str], dict[str, sf.Field]] = {}

    def fields_of(schema: str, version: str) -> dict[str, sf.Field]:
        key = (schema, version)
        if key not in fields_cache:
            fields_cache[key] = sf.expand(registry.get_schema(schema, version).document)
        return fields_cache[key]

    def resource(ch: dict[str, Any]) -> dict[str, Any]:
        res: dict[str, Any] = {
            "index": ch["index"],
            "schema": ch["schema"],
            "version": ch["version"],
        }
        if "path" in ch:
            res["path"] = ch["path"]
        return res

    # 1) remove_field / change_type 必须指向已注册字段；add_field 不得落在
    #    已注册字段上。
    for ch in changes:
        if ch["changeType"] not in _PATH_TYPES:
            continue
        exists = ch["path"] in fields_of(ch["schema"], ch["version"])
        if ch["changeType"] in (REMOVE_FIELD, CHANGE_TYPE) and not exists:
            conflicts.append(
                {
                    "code": FIELD_NOT_FOUND,
                    "index": ch["index"],
                    "resources": [resource(ch)],
                }
            )
        elif ch["changeType"] == ADD_FIELD and exists:
            conflicts.append(
                {
                    "code": CHANGE_CONFLICT,
                    "index": ch["index"],
                    "resources": [resource(ch)],
                }
            )

    # 2) 同一路径被不同变更类型覆盖：批次矛盾（在较晚的条目上报）。
    by_path: dict[tuple[str, str, str], list[dict[str, Any]]] = {}
    for ch in changes:
        if ch["changeType"] in _PATH_TYPES:
            by_path.setdefault((ch["schema"], ch["version"], ch["path"]), []).append(ch)
    for group in by_path.values():
        if len({ch["changeType"] for ch in group}) <= 1:
            continue
        group.sort(key=lambda ch: ch["index"])
        resources = [resource(ch) for ch in group]
        for ch in group[1:]:
            conflicts.append(
                {"code": CHANGE_CONFLICT, "index": ch["index"], "resources": resources}
            )

    # 3) unregister_schema 与同版本任何其他变更并存：批次矛盾。
    by_version: dict[tuple[str, str], list[dict[str, Any]]] = {}
    for ch in changes:
        by_version.setdefault((ch["schema"], ch["version"]), []).append(ch)
    for group in by_version.values():
        unreg = [ch for ch in group if ch["changeType"] == UNREGISTER_SCHEMA]
        others = [ch for ch in group if ch["changeType"] != UNREGISTER_SCHEMA]
        if not unreg or not others:
            continue
        combined = sorted(unreg + others, key=lambda ch: ch["index"])
        resources = [resource(ch) for ch in combined]
        for ch in combined[1:]:
            conflicts.append(
                {"code": CHANGE_CONFLICT, "index": ch["index"], "resources": resources}
            )

    # 同一 (code, index) 可能因多条规则重复出现，去重后按 (index, code) 排序。
    out: list[dict[str, Any]] = []
    seen: set[tuple[str, int]] = set()
    for c in sorted(conflicts, key=lambda c: (c["index"], c["code"])):
        key = (c["code"], c["index"])
        if key in seen:
            continue
        seen.add(key)
        out.append(c)
    return out


# ---------------------------------------------------------------- 影响汇总
def _collect_impacts(
    registry: Registry,
    changes: list[dict[str, Any]],
    reports: dict[int, dict[str, Any]],
) -> dict[str, list[dict[str, Any]]]:
    direct: list[dict[str, Any]] = []
    transitive: list[dict[str, Any]] = []

    def add_impacts(
        ch: dict[str, Any], path: str, impacts: dict, compatibility: str
    ) -> None:
        source = {"index": ch["index"], "changeType": ch["changeType"]}
        for a in impacts["direct_assets"]:
            direct.append(
                {
                    "asset_id": a["asset_id"],
                    "name": a["name"],
                    "kind": a["kind"],
                    "schema": ch["schema"],
                    "version": ch["version"],
                    "path": path,
                    "compatibility": compatibility,
                    "source": source,
                }
            )
        for a in impacts["transitive_assets"]:
            transitive.append(
                {
                    "asset_id": a["asset_id"],
                    "name": a["name"],
                    "kind": a["kind"],
                    "schema": a["schema"],
                    "version": a["version"],
                    "path": a["path"],
                    "matched_paths": list(a["matched_paths"]),
                    "compatibility": compatibility,
                    "source": source,
                }
            )

    for ch in changes:
        ctype = ch["changeType"]
        if ctype == ADD_FIELD:
            continue  # 新字段尚无资产引用，无影响
        if ctype in (REMOVE_FIELD, CHANGE_TYPE):
            impacts = analyze_field(registry, ch["schema"], ch["version"], ch["path"])
            if ctype == REMOVE_FIELD:
                compatibility = compare_mod.BREAKING
            else:
                old = sf.expand(
                    registry.get_schema(ch["schema"], ch["version"]).document
                )[ch["path"]].schema
                compatibility = sf.classify_pair(old, ch["definition"])
            add_impacts(ch, ch["path"], impacts, compatibility)
        elif ctype == COMPATIBILITY_CHECK:
            for change in reports[ch["index"]]["changes"]:
                add_impacts(
                    ch,
                    change["path"],
                    {
                        "direct_assets": change["direct_assets"],
                        "transitive_assets": change["transitive_assets"],
                    },
                    change["compatibility"],
                )
        elif ctype == UNREGISTER_SCHEMA:
            impacts = _unregister_impacts(registry, ch["schema"], ch["version"])
            add_impacts(ch, "", impacts, compare_mod.BREAKING)

    def impact_key(item: dict[str, Any]) -> tuple:
        return (
            item["schema"],
            item["version"],
            item["asset_id"],
            item["path"],
            item["source"]["index"],
        )

    direct.sort(key=impact_key)
    transitive.sort(key=impact_key)
    return {"direct": direct, "transitive": transitive}


def _compat_report(registry: Registry, ch: dict[str, Any]) -> dict[str, Any]:
    """compatibility_check 的字段级比较报告（只读，不入库）。

    旧版本未定义的扩展字段不新增要求：``added`` 条目一律按
    ``compatible`` 计入预览。
    """
    report = compare_mod.build_report(
        registry,
        ch["schema"],
        ch["version"],
        copy.deepcopy(ch["candidate"]),
        None,
        None,
    )
    for change in report["changes"]:
        if change["change_kind"] == compare_mod.ADDED:
            change["compatibility"] = compare_mod.COMPATIBLE
    return report


def _unregister_impacts(registry: Registry, schema: str, version: str) -> dict[str, Any]:
    """注销整个版本的影响：直接引用该版本的资产 + 经其他 Schema 传递到达的。"""
    outgoing = _build_outgoing(registry)
    cache: dict[tuple[str, str, str], list] = {}
    direct: dict[str, dict[str, Any]] = {}
    transitive: list[dict[str, Any]] = []
    for asset in registry.all_assets():
        for ref in asset.refs:
            if ref.schema == schema and ref.version == version:
                direct.setdefault(
                    asset.id,
                    {"asset_id": asset.id, "name": asset.name, "kind": asset.kind},
                )
                continue
            reached = forward_reach(
                registry, ref.schema, ref.version, ref.path, outgoing, cache
            )
            matched = sorted(
                {r.path for r in reached if r.schema == schema and r.version == version},
                key=lambda p: (ptr.parse(p), p),
            )
            if matched:
                transitive.append(
                    {
                        "asset_id": asset.id,
                        "name": asset.name,
                        "kind": asset.kind,
                        "schema": ref.schema,
                        "version": ref.version,
                        "path": ref.path,
                        "matched_paths": matched,
                    }
                )
    if len(direct) + len(transitive) > limits.MAX_IMPACT_ASSETS:
        raise ImpactAnalysisTooLarge(
            "影响资产数量超过公开限制",
            details={"reason": "assets_exceeded", "limit": limits.MAX_IMPACT_ASSETS},
        )
    return {
        "direct_assets": [direct[k] for k in sorted(direct)],
        "transitive_assets": transitive,
    }


# ---------------------------------------------------------------- 检索预览
def _build_search_preview(
    registry: Registry,
    index: SearchIndex,
    changes: list[dict[str, Any]],
    reports: dict[int, dict[str, Any]],
    search_kwargs: dict[str, Any] | None,
) -> dict[str, list[dict[str, Any]]]:
    """预测索引层面的新增/移除/替换文档（可选地按 search 条件过滤）。"""
    replaced: dict[tuple[str, str], dict[str, Any]] = {}
    removed: dict[tuple[str, str], dict[str, Any]] = {}
    added: list[dict[str, Any]] = []

    def schema_entry(ch: dict[str, Any]) -> dict[str, Any]:
        return {
            "id": f"schema:{ch['schema']}@{ch['version']}",
            "type": "schema",
            "schema": ch["schema"],
            "version": ch["version"],
            "report_id": None,
            "path": None,
            "index": ch["index"],
            "reason": ch["changeType"],
        }

    for ch in changes:
        ctype = ch["changeType"]
        key = (ch["schema"], ch["version"])
        if ctype in (ADD_FIELD, REMOVE_FIELD, CHANGE_TYPE):
            if key not in removed and key not in replaced:
                replaced[key] = schema_entry(ch)
        elif ctype == UNREGISTER_SCHEMA:
            replaced.pop(key, None)
            removed[key] = schema_entry(ch)
        elif ctype == COMPATIBILITY_CHECK:
            report = reports[ch["index"]]
            for seq, change in enumerate(report["changes"]):
                added.append(
                    {
                        "id": f"change:{report['report_id']}:{seq}",
                        "type": "change",
                        "schema": report["schema"],
                        "version": report["baseline_version"],
                        "report_id": report["report_id"],
                        "path": change["path"],
                        "index": ch["index"],
                        "reason": COMPATIBILITY_CHECK,
                    }
                )

    if search_kwargs is not None:
        schema_hits = {
            (h["name"], h["version"])
            for h in index.search(**search_kwargs)
            if h["type"] == "schema"
        }
        replaced = {k: v for k, v in replaced.items() if k in schema_hits}
        removed = {k: v for k, v in removed.items() if k in schema_hits}
        added = _filter_added_by_search(reports, added, search_kwargs)

    def preview_key(item: dict[str, Any]) -> tuple:
        return (
            item["schema"] or "",
            item["version"] or "",
            item["report_id"] or "",
            item["path"] or "",
            item["index"],
        )

    return {
        "added": sorted(added, key=preview_key),
        "removed": sorted(removed.values(), key=preview_key),
        "replaced": sorted(replaced.values(), key=preview_key),
    }


def _filter_added_by_search(
    reports: dict[int, dict[str, Any]],
    added: list[dict[str, Any]],
    search_kwargs: dict[str, Any],
) -> list[dict[str, Any]]:
    """在临时索引上模拟新增变更文档的检索命中（不写入真实索引）。"""
    if not added:
        return added
    temp = SearchIndex()
    for entry in added:
        report = reports[entry["index"]]
        seq = int(entry["id"].rsplit(":", 1)[1])
        key, text_fields, payload = change_doc(report, report["changes"][seq], seq)
        temp.add_doc("change", key, text_fields, {**payload, "_preview_id": entry["id"]})
    matched = {h["_preview_id"] for h in temp.search(**search_kwargs)}
    return [e for e in added if e["id"] in matched]

import unittest

from meta_catalog import MetaCatalog, limits
from meta_catalog.errors import ImpactAnalysisTooLarge


class LimitTests(unittest.TestCase):
    def test_too_many_fields(self):
        c = MetaCatalog()
        old_props = {f"f{i}": {"type": "string"} for i in range(5)}
        c.register_schema("Big", "1.0", {"type": "object", "properties": old_props})
        old_limit = limits.MAX_FIELDS
        limits.MAX_FIELDS = 3
        try:
            with self.assertRaises(ImpactAnalysisTooLarge) as cm:
                c.compare_schemas("Big", "1.0", {"type": "object", "properties": old_props})
            self.assertEqual(cm.exception.details["reason"], "fields_exceeded")
        finally:
            limits.MAX_FIELDS = old_limit

    def test_too_many_changes(self):
        c = MetaCatalog()
        old_props = {f"f{i}": {"type": "string"} for i in range(5)}
        c.register_schema("Big", "1.0", {"type": "object", "properties": old_props})
        # 删除全部字段 -> 5 条变更
        old_limit = limits.MAX_CHANGES
        limits.MAX_CHANGES = 3
        try:
            with self.assertRaises(ImpactAnalysisTooLarge) as cm:
                c.compare_schemas("Big", "1.0", {"type": "object"})
            self.assertEqual(cm.exception.details["reason"], "changes_exceeded")
        finally:
            limits.MAX_CHANGES = old_limit

    def test_impact_chain_depth_limit(self):
        c = MetaCatalog()
        c.register_schema("S0", "1.0", {"type": "object", "properties": {"x": {"type": "string"}}})
        # 构造 S1 -> S0, S2 -> S1 ... 链式引用
        for i in range(1, 6):
            doc = {
                "type": "object",
                "properties": {"nested": {"$ref": f"S{i-1}@1.0#"}},
            }
            c.register_schema(f"S{i}", "1.0", doc)
        # 资产引用链末端字段，正向解析需沿 5 条边到达 S0:/x
        c.register_asset(
            "svc-deep", "深层服务", "service",
            [{"schema": "S5", "version": "1.0",
              "path": "/" + "/".join(["nested"] * 5 + ["x"])}],
        )
        old = limits.MAX_IMPACT_DEPTH
        limits.MAX_IMPACT_DEPTH = 2
        try:
            with self.assertRaises(ImpactAnalysisTooLarge) as cm:
                c.analyze_impact("S0", "1.0", "/x")
            self.assertEqual(cm.exception.details["reason"], "depth_exceeded")
        finally:
            limits.MAX_IMPACT_DEPTH = old


class RenameSubtreeTests(unittest.TestCase):
    def test_renamed_subtree_partial_delete_and_add(self):
        c = MetaCatalog()
        v1 = {
            "type": "object",
            "properties": {
                "a": {
                    "type": "object",
                    "properties": {
                        "x": {"type": "string"},
                        "y": {"type": "string"},
                    },
                }
            },
        }
        v2 = {
            "type": "object",
            "properties": {
                "b": {
                    "type": "object",
                    "properties": {
                        "x": {"type": "string"},   # 对齐保留
                        "z": {"type": "string"},   # 新增
                    },
                }
            },
        }
        c.register_schema("Doc", "1.0", v1)
        rep = c.compare_schemas(
            "Doc", "1.0", v2, renames=[{"from": "/a", "to": "/b"}]
        )
        rows = {(ch["old_path"], ch["new_path"], ch["change_kind"]) for ch in rep["changes"]}
        # 根恰一次 rename
        self.assertIn(("/a", "/b", "rename"), rows)
        # 未被映射覆盖的删除 /a/y 与新增 /b/z 仍分别呈现
        self.assertIn(("/a/y", None, "deleted"), rows)
        self.assertIn((None, "/b/z", "added"), rows)
        # 对齐保留的 x 不产生条目
        self.assertFalse(any(r[0] == "/a/x" for r in rows))

    def test_overlapping_rename_endpoints_rejected(self):
        from meta_catalog.errors import SchemaComparisonInvalid

        c = MetaCatalog()
        v1 = {"type": "object", "properties": {"a": {
            "type": "object",
            "properties": {"x": {"type": "string"}},
        }}}
        v2 = {"type": "object", "properties": {"b": {
            "type": "object",
            "properties": {"y": {"type": "string"}},
        }}}
        c.register_schema("D", "1.0", v1)
        with self.assertRaises(SchemaComparisonInvalid) as cm:
            c.compare_schemas(
                "D", "1.0", v2,
                renames=[{"from": "/a", "to": "/b"},
                         {"from": "/a/x", "to": "/b/y"}],
            )
        self.assertEqual(cm.exception.details["reason"], "rename_overlapping")


class ReportShapeTests(unittest.TestCase):
    def test_entry_contains_required_fields(self):
        c = MetaCatalog()
        c.register_schema("P", "1.0", {"type": "object", "properties": {
            "age": {"type": "integer"}}})
        rep = c.compare_schemas(
            "P", "1.0",
            {"type": "object", "properties": {"age": {"type": "number"}}},
            candidate_version="2.0",
        )
        (entry,) = rep["changes"]
        for key in (
            "path", "old_path", "new_path", "old_summary", "new_summary",
            "change_kind", "compatibility", "direct_assets", "transitive_assets",
        ):
            self.assertIn(key, entry)
        self.assertEqual(entry["old_summary"], {"type": "integer"})
        self.assertEqual(entry["new_summary"], {"type": "number"})
        self.assertEqual(rep["schema"], "P")
        self.assertEqual(rep["baseline_version"], "1.0")
        self.assertEqual(rep["candidate_version"], "2.0")


